<?php use App\Services\Navigation;cms_view('public/hero',compact('page'));$filterUrl=static fn(array $changes=[])=>url('/products/?'.http_build_query(array_filter(array_replace(array_intersect_key(request()->query(),array_flip(['brand','category','sub_category','q'])),$changes),fn($v)=>$v!==''&&$v!==null)));?>
<main><section class="section-padding product-catalog <?=$view!=='products'?'catalog-browse-page':''?>"><div class="container">
<?php if($view!=='products'):$records=match($view){'brands'=>$brands,'categories'=>$categories,default=>$subcategories};$module=$view==='sub_categories'?'subcategories':$view;?><div class="catalog-toolbar"><div><span class="section-kicker"><?=text('browse')?></span><h2 class="section-title"><?=text('all_'.$module)?></h2><p class="section-desc"><?=text('browse_intro')?></p></div><a class="catalog-reset" href="<?=e(cms_url('/products/'))?>"><?=text('products')?></a></div><div class="catalog-browse-grid catalog-card-grid"><?php foreach($records as $record):?><div class="catalog-browse-item reveal"><a class="catalog-browse-card <?=$view==='brands'?'catalog-brand-card':''?>" href="<?=e(cms_url(Navigation::recordUrl($module,$record)))?>"><span class="catalog-browse-media"><?php if($record['image_id']):?><?=media_img($record['image_id'],$record['title'])?><?php else:?><i class="<?=e(($record['icon']??'')?:'fa-solid fa-box')?>"></i><?php endif?></span><strong><?=e($record['title'])?></strong><small><?=e(mb_strimwidth($record['description']??'',0,100,'…'))?></small></a></div><?php endforeach?><?php if(!$records):?><div class="catalog-empty"><h3><?=text('no_data')?></h3></div><?php endif?></div>
<?php else:?><div class="catalog-layout"><?php cms_view('public/catalogue-sidebar',compact('filters','brandCategories','brands','filterUrl'));?><div class="catalog-main"><nav class="sub-category-nav catalog-filter-bar" aria-label="<?=text('categories')?>"><div class="catalog-filter-scroll" tabindex="0"><a class="<?=!$filters['category']?'active':''?>" href="<?=e($filterUrl(['category'=>null,'sub_category'=>null]))?>"><?=text('all_categories')?></a><?php foreach($categories as $category):?><a class="<?=($filters['category']['id']??null)===$category['id']?'active':''?>" href="<?=e($filterUrl(['category'=>$category['title'],'sub_category'=>null]))?>"><?=e($category['title'])?></a><?php endforeach?></div><?php if($filters['brand']):?><a class="catalog-brochure-link" href="<?=e(cms_url('/brochures/?brand='.$filters['brand']['id']))?>"><i class="fa-regular fa-file-pdf"></i> <?=text('view_brochures')?></a><?php endif?></nav>
<?php if($filters['category']||$filters['brand']):?><nav class="sub-category-nav" aria-label="<?=text('subcategories')?>"><a class="<?=!$filters['sub_category']?'active':''?>" href="<?=e($filterUrl(['sub_category'=>null]))?>"><?=text('all_subcategories')?></a><?php foreach($subcategories as $sub):if($filters['category']&&(int)$sub['category_id']!==(int)$filters['category']['id'])continue;?><a class="<?=($filters['sub_category']['id']??null)===$sub['id']?'active':''?>" href="<?=e($filterUrl(['sub_category'=>$sub['id']]))?>"><?=e($sub['title'])?></a><?php endforeach?></nav><?php endif?>
<div class="catalog-heading-row"><h2><?=text('products')?></h2><div class="catalog-heading-actions"><form class="catalog-search-form" action="<?=e(cms_url('/products/'))?>" role="search"><?php foreach($filters as $key=>$filter):if($filter):?><input type="hidden" name="<?=e($key)?>" value="<?=e($filter['id'])?>"><?php endif;endforeach?><input id="product-search" type="search" name="q" value="<?=e($q)?>" placeholder="<?=text('product_search')?>" aria-label="<?=text('product_search')?>"><button><i class="fa-solid fa-magnifying-glass"></i><span><?=text('search')?></span></button></form><?php if($q||array_filter($filters)):?><a class="catalog-reset" href="<?=e(cms_url('/products/'))?>"><i class="fa-solid fa-rotate-left"></i><?=text('reset')?></a><?php endif?></div></div>
<div class="catalog-products-grid"><?php foreach($products as $product)cms_view('public/product-card',compact('product'));?><?php if(!$products):?><div class="catalog-empty"><i class="fa-solid fa-box-open"></i><h3><?=text('no_data')?></h3><p><?=text('no_products')?></p></div><?php endif?></div><?php cms_view('public/pagination',compact('total','number','perPage'));?></div></div><?php endif?></div></section><?php if($page['body']):?><section class="section-padding"><div class="container rich-text"><?=rich($page['body'])?></div></section><?php endif?><?php foreach($sections as $section)cms_view('public/section',compact('section'));?></main>
